  return <>
  <Root/>
  </>
}

function Screen() {
  function server() {
    return {
      connect() {console.log("online")},
      disconnect() {console.log("offline")}
    }
  }
  useEffect(() => {
    const connection = server()
    connection.connect()
    return connection.disconnect()
  }, [])
  return <>
  <p>checking</p>
  </>
}

